ALTER TABLE "stock_movements" ADD CONSTRAINT "stock_movements_reason_signs_valid" CHECK (("stock_movements"."reason" IN ('opening','receive','compensate','return') AND "stock_movements"."delta_on_hand">0 AND "stock_movements"."delta_reserved"=0) OR ("stock_movements"."reason"='adjust' AND "stock_movements"."delta_on_hand"<>0 AND "stock_movements"."delta_reserved"=0) OR ("stock_movements"."reason"='reserve' AND "stock_movements"."delta_on_hand"=0 AND "stock_movements"."delta_reserved">0) OR ("stock_movements"."reason"='release' AND "stock_movements"."delta_on_hand"=0 AND "stock_movements"."delta_reserved"<0 AND "stock_movements"."reservation_line_id" IS NOT NULL) OR ("stock_movements"."reason"='consume' AND "stock_movements"."delta_on_hand"<0 AND "stock_movements"."delta_on_hand"="stock_movements"."delta_reserved" AND "stock_movements"."reservation_line_id" IS NOT NULL AND "stock_movements"."allocation_id" IS NOT NULL));